import{_ as t,o as i,c as n,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Traitement des Quatre Branches des Entités de Remplacement Sombres","description":"","frontmatter":{},"headers":[],"relativePath":"fr/59-黑暗置换体四类分支处置.md","filePath":"fr/59-黑暗置换体四类分支处置.md","lastUpdated":null}'),a={name:"fr/59-黑暗置换体四类分支处置.md"};function r(d,e,l,o,u,m){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="traitement-des-quatre-branches-des-entites-de-remplacement-sombres" tabindex="-1">Traitement des Quatre Branches des Entités de Remplacement Sombres <a class="header-anchor" href="#traitement-des-quatre-branches-des-entites-de-remplacement-sombres" aria-label="Permalink to &quot;Traitement des Quatre Branches des Entités de Remplacement Sombres&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>59</td></tr><tr><td>Module</td><td>Races et Formes de Vie</td></tr><tr><td>Mots clés</td><td>Fusion symbiotique, séparation et réinstallation, scellement et surveillance, dissolution, traitement par branches</td></tr></tbody></table><h2 id="i-cadre-general-du-traitement-par-branches" tabindex="-1">I. Cadre Général du Traitement par Branches <a class="header-anchor" href="#i-cadre-general-du-traitement-par-branches" aria-label="Permalink to &quot;I. Cadre Général du Traitement par Branches&quot;">​</a></h2><p>Le traitement des Entités de Remplacement Sombres est le domaine le plus complexe de la gouvernance de la vie de la Civilisation Symbiotique de l&#39;Ancre. Contrairement aux processus de traitement en trois types pour la vie anomale et l&#39;énergie anomale, les Entités de Remplacement Sombres, en raison de leur structure spéciale de coexistence des deux âmes (voir <em>57-黑暗置换体起源与本质</em>), nécessitent des plans de traitement par branches plus raffinés. Selon les principes éthiques établis dans <em>58-双魂伦理准则</em>, combinés au stade de développement de l&#39;Entité de Remplacement Sombre, à l&#39;état de l&#39;âme maîtresse d&#39;origine, aux caractéristiques de l&#39;âme sombre et au niveau de risque, le traitement des Entités de Remplacement Sombres est divisé en quatre branches : type fusion symbiotique, type séparation et réinstallation, type scellement et surveillance, et type dissolution.</p><p>La sélection des quatre traitements par branches suit la logique décisionnelle suivante :</p><table tabindex="0"><thead><tr><th>Facteur décisionnel</th><th>Points d&#39;examen</th></tr></thead><tbody><tr><td>Stade de développement</td><td>Les premier au troisième stades privilégient le sauvetage ; le quatrième stade est évalué avec prudence ; au cinquième stade, l&#39;hôte d&#39;origine a péri</td></tr><tr><td>État de l&#39;âme maîtresse d&#39;origine</td><td>Si l&#39;âme maîtresse d&#39;origine existe encore, si elle peut exprimer sa volonté, s&#39;il y a une possibilité de récupération</td></tr><tr><td>Caractéristiques de l&#39;âme sombre</td><td>Si l&#39;âme sombre a un potentiel de communication, s&#39;il y a une marge de réforme, le degré de destructivité</td></tr><tr><td>Niveau de risque</td><td>Le degré de menace pour la sécurité publique et les droits et intérêts d&#39;autrui</td></tr><tr><td>Conclusion de l&#39;examen éthique</td><td>L&#39;avis d&#39;examen et la décision du Comité d&#39;examen éthique des deux âmes</td></tr><tr><td>Volonté de l&#39;hôte d&#39;origine</td><td>Le choix de l&#39;âme maîtresse d&#39;origine lorsqu&#39;elle peut exprimer sa volonté</td></tr></tbody></table><h2 id="ii-premier-type-traitement-de-fusion-symbiotique" tabindex="-1">II. Premier Type : Traitement de Fusion Symbiotique <a class="header-anchor" href="#ii-premier-type-traitement-de-fusion-symbiotique" aria-label="Permalink to &quot;II. Premier Type : Traitement de Fusion Symbiotique&quot;">​</a></h2><p>Le traitement de fusion symbiotique est le traitement le plus positif et le plus constructif parmi les quatre branches, applicable aux Entités de Remplacement Sombres dans lesquelles l&#39;âme maîtresse d&#39;origine et l&#39;âme sombre ont la possibilité de parvenir à une réconciliation et de réaliser une fusion des âmes.</p><h3 id="i-conditions-d-application" tabindex="-1">(I) Conditions d&#39;application <a class="header-anchor" href="#i-conditions-d-application" aria-label="Permalink to &quot;(I) Conditions d&#39;application&quot;">​</a></h3><p>Le traitement de fusion symbiotique doit satisfaire simultanément les conditions suivantes :</p><ol><li>L&#39;Entité de Remplacement Sombre est au troisième stade (période de formation des deux âmes) ou au début du quatrième stade (début de la période de domination sombre) ; l&#39;âme maîtresse d&#39;origine existe encore et possède un certain degré de conscience autonome.</li><li>L&#39;âme maîtresse d&#39;origine exprime clairement la volonté de tenter une fusion avec l&#39;âme sombre, et cette volonté est déterminée comme authentique et autonome.</li><li>L&#39;âme sombre possède une certaine capacité de communication, présente des caractéristiques non purement destructives et a la possibilité d&#39;accepter la fusion.</li><li>Le niveau de risque est évalué comme Deuxième niveau (risque moyen) ou inférieur, et le processus de fusion ne constituera pas une menace incontrôlable pour la sécurité publique.</li><li>Approuvé par l&#39;examen du Comité d&#39;examen éthique des deux âmes.</li></ol><h3 id="ii-objectif-du-traitement" tabindex="-1">(II) Objectif du traitement <a class="header-anchor" href="#ii-objectif-du-traitement" aria-label="Permalink to &quot;(II) Objectif du traitement&quot;">​</a></h3><p>En guidant l&#39;âme maîtresse d&#39;origine et l&#39;âme sombre vers une réconciliation, réaliser la fusion organique des deux âmes, formant une nouvelle âme possédant à la fois les souvenirs, la personnalité et le pouvoir sombre de l&#39;hôte d&#39;origine. La nouvelle âme fusionnée conserve la citoyenneté et les droits légitimes de l&#39;hôte d&#39;origine, tout en obtenant la capacité de manipuler l&#39;énergie sombre, devenant un membre spécial de la civilisation symbiotique.</p><h3 id="iii-etapes-du-traitement" tabindex="-1">(III) Étapes du traitement <a class="header-anchor" href="#iii-etapes-du-traitement" aria-label="Permalink to &quot;(III) Étapes du traitement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Nom</th><th>Contenu spécifique</th><th>Institution responsable</th></tr></thead><tbody><tr><td>Première étape</td><td>Examen éthique</td><td>Le Comité d&#39;examen éthique des deux âmes mène un examen complet du plan de fusion, confirmant la conformité aux principes éthiques</td><td>Comité d&#39;examen éthique des deux âmes</td></tr><tr><td>Deuxième étape</td><td>Guidance de communication</td><td>Dans un environnement contrôlé, des guides d&#39;âmes professionnels assistent l&#39;âme maîtresse d&#39;origine et l&#39;âme sombre dans la communication, favorisant la compréhension mutuelle</td><td>Centre de traitement des âmes + cultivateurs</td></tr><tr><td>Troisième étape</td><td>Négociation de réconciliation</td><td>Guider les deux âmes vers un accord de réconciliation sur l&#39;identité fusionnée, les souvenirs, les capacités, les normes de comportement, etc.</td><td>Centre de traitement des âmes + conseillers juridiques</td></tr><tr><td>Quatrième étape</td><td>Préparation de la fusion</td><td>Mener les préparatifs pré-fusion tels que le conditionnement corporel, l&#39;équilibrage énergétique et la construction psychologique</td><td>Équipe médicale + instructeurs de culture</td></tr><tr><td>Cinquième étape</td><td>Fusion des âmes</td><td>Avec l&#39;assistance conjointe de cultivateurs avancés et de thérapeutes des âmes, mettre en œuvre la chirurgie/le rituel de fusion des âmes</td><td>Cultivateurs avancés + thérapeutes des âmes</td></tr><tr><td>Sixième étape</td><td>Stabilisation post-fusion</td><td>Mener un traitement de stabilisation pour la nouvelle âme fusionnée, surveillant l&#39;intégrité de l&#39;âme et l&#39;adaptabilité du corps</td><td>Équipe médicale + équipe de surveillance</td></tr><tr><td>Septième étape</td><td>Confirmation d&#39;identité</td><td>Confirmer l&#39;identité de la nouvelle âme fusionnée, conserver la citoyenneté de l&#39;hôte d&#39;origine et mettre à jour les archives d&#39;identité</td><td>Institution d&#39;enregistrement des ménages + Bureau d&#39;Administration de la Vie</td></tr><tr><td>Huitième étape</td><td>Aide à l&#39;intégration</td><td>Fournir des services auxiliaires tels que le soutien psychologique, la guidance de culture et l&#39;intégration sociale pour l&#39;individu fusionné</td><td>Département des Affaires des Dix Mille Races + communauté</td></tr><tr><td>Neuvième étape</td><td>Suivi à long terme</td><td>Mener un suivi et une surveillance à long terme de l&#39;individu fusionné pendant au moins cinq ans, évaluant la stabilité de la fusion et l&#39;adaptabilité sociale</td><td>Bureau d&#39;Administration de la Vie + communauté</td></tr></tbody></table><h3 id="iv-gestion-post-fusion" tabindex="-1">(IV) Gestion post-fusion <a class="header-anchor" href="#iv-gestion-post-fusion" aria-label="Permalink to &quot;(IV) Gestion post-fusion&quot;">​</a></h3><p>Bien que l&#39;individu fusionné conserve la citoyenneté de l&#39;hôte d&#39;origine, il doit accepter une gestion spéciale :</p><ul><li><strong>Contrôle énergétique</strong> : l&#39;utilisation de l&#39;énergie sombre par l&#39;individu fusionné est strictement contrôlée ; des inspections énergétiques périodiques sont requises, et l&#39;utilisation de l&#39;énergie sombre dans les lieux publics est interdite.</li><li><strong>Supervision comportementale</strong> : l&#39;individu fusionné doit périodiquement rendre compte de son état comportemental au Bureau d&#39;Administration de la Vie et accepter la supervision et l&#39;aide de la communauté.</li><li><strong>Restrictions de culture</strong> : l&#39;individu fusionné ne peut pas cultiver des techniques susceptibles d&#39;aggraver les attributs sombres ; les plans de culture doivent être approuvés.</li><li><strong>Plan d&#39;urgence</strong> : établir un plan d&#39;urgence pour la perte de contrôle de l&#39;énergie sombre chez les individus fusionnés ; dès l&#39;apparition de signes de perte de contrôle, activer immédiatement le contrôle.</li><li><strong>Mécanisme de sortie</strong> : si une instabilité grave ou un comportement dangereux persistant apparaît après la fusion, une réévaluation peut être menée et le type de traitement converti.</li></ul><h3 id="v-gestion-de-l-echec-de-la-fusion" tabindex="-1">(V) Gestion de l&#39;échec de la fusion <a class="header-anchor" href="#v-gestion-de-l-echec-de-la-fusion" aria-label="Permalink to &quot;(V) Gestion de l&#39;échec de la fusion&quot;">​</a></h3><p>La fusion des âmes comporte un risque d&#39;échec ; les plans de gestion de l&#39;échec de la fusion :</p><ul><li><strong>Interruption de la fusion</strong> : si une instabilité grave survient pendant le processus de fusion, interrompre immédiatement la fusion et restaurer les deux âmes à leur état pré-fusion.</li><li><strong>Fusion incomplète</strong> : si une incomplétude de l&#39;âme ou un dédoublement de personnalité apparaît après la fusion, passer au traitement de séparation et de réinstallation pour la suite.</li><li><strong>Perte de contrôle de la fusion</strong> : si la nouvelle âme après la fusion présente une destructivité incontrôlable, passer immédiatement au traitement de scellement et de surveillance ou de dissolution.</li></ul><h2 id="iii-deuxieme-type-traitement-de-separation-et-de-reinstallation" tabindex="-1">III. Deuxième Type : Traitement de Séparation et de Réinstallation <a class="header-anchor" href="#iii-deuxieme-type-traitement-de-separation-et-de-reinstallation" aria-label="Permalink to &quot;III. Deuxième Type : Traitement de Séparation et de Réinstallation&quot;">​</a></h2><p>Le traitement de séparation et de réinstallation s&#39;applique aux Entités de Remplacement Sombres dans lesquelles l&#39;âme maîtresse d&#39;origine et l&#39;âme sombre ne peuvent pas fusionner mais peuvent être séparées ; par une chirurgie de séparation des âmes, les deux âmes sont séparées et réinstallées respectivement.</p><h3 id="i-conditions-d-application-1" tabindex="-1">(I) Conditions d&#39;application <a class="header-anchor" href="#i-conditions-d-application-1" aria-label="Permalink to &quot;(I) Conditions d&#39;application&quot;">​</a></h3><ol><li>L&#39;Entité de Remplacement Sombre est au troisième ou quatrième stade ; l&#39;âme maîtresse d&#39;origine existe encore et a une possibilité de récupération.</li><li>La tentative de fusion des deux âmes a échoué ou ne dispose pas des conditions de fusion.</li><li>L&#39;évaluation technique juge la séparation des âmes faisable, et l&#39;âme maîtresse d&#39;origine peut survivre indépendamment après la séparation.</li><li>L&#39;âme maîtresse d&#39;origine exprime clairement la volonté d&#39;être séparée.</li><li>Approuvé par l&#39;examen du Comité d&#39;examen éthique des deux âmes.</li></ol><h3 id="ii-objectif-du-traitement-1" tabindex="-1">(II) Objectif du traitement <a class="header-anchor" href="#ii-objectif-du-traitement-1" aria-label="Permalink to &quot;(II) Objectif du traitement&quot;">​</a></h3><p>Par une chirurgie de séparation des âmes, séparer l&#39;âme maîtresse d&#39;origine de l&#39;âme sombre ; l&#39;âme maîtresse d&#39;origine retourne dans le corps pour reprendre une vie normale, tandis que l&#39;âme sombre est placée dans un conteneur ou une installation dédié pour le contrôle et la recherche.</p><h3 id="iii-etapes-du-traitement-1" tabindex="-1">(III) Étapes du traitement <a class="header-anchor" href="#iii-etapes-du-traitement-1" aria-label="Permalink to &quot;(III) Étapes du traitement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Nom</th><th>Contenu spécifique</th><th>Institution responsable</th></tr></thead><tbody><tr><td>Première étape</td><td>Examen éthique</td><td>Le Comité d&#39;examen éthique des deux âmes examine le plan de séparation, confirmant la nécessité et la faisabilité de la séparation</td><td>Comité d&#39;examen éthique des deux âmes</td></tr><tr><td>Deuxième étape</td><td>Préparation de la séparation</td><td>Mener les préparatifs pré-séparation tels que l&#39;évaluation corporelle, l&#39;inspection de l&#39;état de l&#39;âme et l&#39;ajustement de l&#39;équilibre énergétique</td><td>Équipe médicale + thérapeutes des âmes</td></tr><tr><td>Troisième étape</td><td>Séparation des âmes</td><td>Avec l&#39;assistance de cultivateurs avancés et de thérapeutes des âmes, mettre en œuvre la chirurgie de séparation des âmes pour séparer les deux âmes du corps</td><td>Cultivateurs avancés + thérapeutes des âmes</td></tr><tr><td>Quatrième étape</td><td>Repositionnement de l&#39;hôte d&#39;origine</td><td>Réimplanter l&#39;âme maîtresse d&#39;origine dans le corps, menant une stabilisation de l&#39;âme et une rééducation corporelle</td><td>Équipe médicale</td></tr><tr><td>Cinquième étape</td><td>Placement de l&#39;âme sombre</td><td>Placer l&#39;âme sombre séparée dans un conteneur de containment d&#39;âme dédié et la stocker dans une installation de scellement des âmes</td><td>Bureau d&#39;Administration de la Vie + équipe technique</td></tr><tr><td>Sixième étape</td><td>Récupération de l&#39;hôte d&#39;origine</td><td>Mener une rééducation corporelle complète, un traitement psychologique et une récupération de culture pour l&#39;hôte d&#39;origine, l&#39;aidant à reprendre une vie normale</td><td>Équipe médicale + conseillers psychologiques</td></tr><tr><td>Septième étape</td><td>Restauration d&#39;identité</td><td>Confirmer la restauration complète de l&#39;identité et des droits de l&#39;hôte d&#39;origine et mettre à jour les archives d&#39;identité</td><td>Institution d&#39;enregistrement des ménages</td></tr><tr><td>Huitième étape</td><td>Gestion de l&#39;âme sombre</td><td>Mener une surveillance et une recherche continues sur l&#39;âme sombre séparée, explorant la possibilité de sa réforme ou de sa dissolution</td><td>Bureau d&#39;Administration de la Vie + institution de recherche scientifique</td></tr></tbody></table><h3 id="iv-placement-de-l-ame-sombre-separee" tabindex="-1">(IV) Placement de l&#39;âme sombre séparée <a class="header-anchor" href="#iv-placement-de-l-ame-sombre-separee" aria-label="Permalink to &quot;(IV) Placement de l&#39;âme sombre séparée&quot;">​</a></h3><p>L&#39;âme sombre séparée est placée de la manière suivante :</p><ul><li><strong>Conteneur d&#39;âme</strong> : l&#39;âme sombre est placée dans un conteneur de containment d&#39;âme dédié équipé de dispositifs tels que le blindage énergétique, la suppression de la conscience et le verrouillage de sécurité.</li><li><strong>Installation de scellement</strong> : le conteneur est stocké dans une installation de scellement des âmes dédiée qui met en œuvre le plus haut niveau de gestion de sécurité.</li><li><strong>Surveillance continue</strong> : mener une surveillance continue 24 heures sur 24 de l&#39;activité de conscience et des fluctuations énergétiques de l&#39;âme sombre.</li><li><strong>Recherche et utilisation</strong> : sous un examen éthique strict, des recherches scientifiques peuvent être menées sur l&#39;âme sombre, explorant l&#39;essence de l&#39;Énergie des Abysses et les méthodes de purification.</li><li><strong>Traitement final</strong> : selon les résultats de recherche et l&#39;évaluation des risques, prendre une décision de traitement final pour l&#39;âme sombre — réforme en existence non destructive, scellement à long terme ou purification et dissolution.</li></ul><h3 id="v-risques-de-la-separation-et-reponses" tabindex="-1">(V) Risques de la séparation et réponses <a class="header-anchor" href="#v-risques-de-la-separation-et-reponses" aria-label="Permalink to &quot;(V) Risques de la séparation et réponses&quot;">​</a></h3><p>La chirurgie de séparation des âmes comporte les risques suivants, pour lesquels des plans de réponse doivent être formulés :</p><table tabindex="0"><thead><tr><th>Risque</th><th>Plan de réponse</th></tr></thead><tbody><tr><td>L&#39;âme maîtresse d&#39;origine est endommagée pendant la séparation</td><td>Renforcer l&#39;âme avant la séparation ; des cultivateurs avancés assurent une protection complète pendant la séparation</td></tr><tr><td>Le corps de l&#39;hôte d&#39;origine ne peut pas s&#39;adapter après la séparation</td><td>Mener une rééducation corporelle complète et un traitement de stabilisation de l&#39;âme après la séparation</td></tr><tr><td>L&#39;âme sombre s&#39;échappe pendant la séparation</td><td>La séparation est menée dans l&#39;installation de sécurité la plus haute, équipée de dispositifs de containment multiples</td></tr><tr><td>Séparation incomplète, énergie sombre résiduelle</td><td>Mener un traitement de purification profonde après la séparation pour éliminer l&#39;énergie sombre résiduelle</td></tr><tr><td>Traumatisme psychologique de l&#39;âme maîtresse d&#39;origine après la séparation</td><td>Fournir un soutien psychologique à long terme et un traitement mental</td></tr></tbody></table><h2 id="iv-troisieme-type-traitement-de-scellement-et-de-surveillance" tabindex="-1">IV. Troisième Type : Traitement de Scellement et de Surveillance <a class="header-anchor" href="#iv-troisieme-type-traitement-de-scellement-et-de-surveillance" aria-label="Permalink to &quot;IV. Troisième Type : Traitement de Scellement et de Surveillance&quot;">​</a></h2><p>Le traitement de scellement et de surveillance s&#39;applique aux Entités de Remplacement Sombres qui ne peuvent ni fusionner ni être séparées, mais dont l&#39;âme maîtresse d&#39;origine existe encore et qui ne remplissent pas les conditions de dissolution immédiate ; par des moyens de scellement, leur danger est contrôlé, avec une surveillance à long terme et une évaluation continue.</p><h3 id="i-conditions-d-application-2" tabindex="-1">(I) Conditions d&#39;application <a class="header-anchor" href="#i-conditions-d-application-2" aria-label="Permalink to &quot;(I) Conditions d&#39;application&quot;">​</a></h3><ol><li>L&#39;Entité de Remplacement Sombre est au quatrième stade (période de domination sombre) ; l&#39;âme maîtresse d&#39;origine est profondément supprimée mais n&#39;a pas encore péri.</li><li>La fusion et la séparation manquent toutes deux de faisabilité technique ou leurs risques sont trop élevés.</li><li>Le niveau de risque de l&#39;Entité de Remplacement Sombre est Troisième niveau (risque élevé), mais n&#39;a pas encore atteint le degré exigeant une dissolution immédiate.</li><li>L&#39;âme maîtresse d&#39;origine a encore un faible espoir de récupération, nécessitant du temps et des conditions pour attendre un tournant.</li><li>Le Comité d&#39;examen éthique des deux âmes examine et approuve le plan de scellement.</li></ol><h3 id="ii-objectif-du-traitement-2" tabindex="-1">(II) Objectif du traitement <a class="header-anchor" href="#ii-objectif-du-traitement-2" aria-label="Permalink to &quot;(II) Objectif du traitement&quot;">​</a></h3><p>Par des moyens de scellement, supprimer le pouvoir et l&#39;activité de l&#39;âme sombre, contrôler le danger de l&#39;Entité de Remplacement Sombre, tout en protégeant l&#39;âme maîtresse d&#39;origine de l&#39;annihilation complète, en attendant dans la surveillance à long terme la maturité des opportunités de récupération ou de traitement.</p><h3 id="iii-methodes-de-scellement" tabindex="-1">(III) Méthodes de scellement <a class="header-anchor" href="#iii-methodes-de-scellement" aria-label="Permalink to &quot;(III) Méthodes de scellement&quot;">​</a></h3><p>Selon le niveau de pouvoir et les caractéristiques de l&#39;Entité de Remplacement Sombre, choisir les méthodes de scellement suivantes :</p><table tabindex="0"><thead><tr><th>Méthode de scellement</th><th>Principe</th><th>Cibles applicables</th></tr></thead><tbody><tr><td>Scellement énergétique</td><td>Utiliser des matrices ou dispositifs de scellement pour supprimer le flux et la sortie de l&#39;énergie sombre</td><td>Entités de Remplacement Sombres de niveau de pouvoir faible à moyen</td></tr><tr><td>Scellement spatial</td><td>Sceller l&#39;Entité de Remplacement Sombre dans un espace isolé indépendant, coupant le contact avec l&#39;extérieur</td><td>Entités de Remplacement Sombres de haut niveau de pouvoir ou infectieuses</td></tr><tr><td>Scellement de conscience</td><td>Supprimer l&#39;activité de conscience de l&#39;âme sombre, la plaçant dans un état dormant ou semi-dormant</td><td>Entités de Remplacement Sombres à conscience active et capacité d&#39;attaque de l&#39;âme</td></tr><tr><td>Scellement multiple</td><td>Utiliser simultanément plusieurs méthodes de scellement pour former des couches de protection multiples</td><td>Entités de Remplacement Sombres de niveau de pouvoir extrêmement élevé ou à multiples caractéristiques dangereuses</td></tr><tr><td>Scellement de l&#39;Ancre</td><td>Utiliser les attributs d&#39;origine de l&#39;énergie de l&#39;Ancre pour le scellement, la méthode de scellement la plus puissante</td><td>Entités de Remplacement Sombres dangereuses au niveau cosmique</td></tr></tbody></table><h3 id="iv-etapes-du-traitement" tabindex="-1">(IV) Étapes du traitement <a class="header-anchor" href="#iv-etapes-du-traitement" aria-label="Permalink to &quot;(IV) Étapes du traitement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Nom</th><th>Contenu spécifique</th><th>Institution responsable</th></tr></thead><tbody><tr><td>Première étape</td><td>Examen éthique</td><td>Le Comité d&#39;examen éthique des deux âmes examine le plan de scellement, confirmant la nécessité et l&#39;opportunité du scellement</td><td>Comité d&#39;examen éthique des deux âmes</td></tr><tr><td>Deuxième étape</td><td>Préparation du scellement</td><td>Préparer la matrice/dispositif/espace de scellement, allouant l&#39;énergie et le personnel requis pour le scellement</td><td>Équipe technique + cultivateurs avancés</td></tr><tr><td>Troisième étape</td><td>Maîtrise et contrôle</td><td>Avec la coopération de l&#39;équipe de sécurité, maîtriser l&#39;Entité de Remplacement Sombre, garantissant qu&#39;aucun accident ne survient pendant le processus de scellement</td><td>Département de Sécurité + cultivateurs avancés</td></tr><tr><td>Quatrième étape</td><td>Mise en œuvre du scellement</td><td>Mettre en œuvre le scellement selon le plan de scellement, supprimant le pouvoir et l&#39;activité de l&#39;âme sombre</td><td>Cultivateurs avancés + scelleurs</td></tr><tr><td>Cinquième étape</td><td>Vérification du scellement</td><td>Vérifier l&#39;efficacité et la stabilité du scellement, confirmant que le danger de l&#39;Entité de Remplacement Sombre a été contrôlé</td><td>Équipe technique + équipe de surveillance</td></tr><tr><td>Sixième étape</td><td>Transfert et installation</td><td>Transférer l&#39;Entité de Remplacement Sombre scellée vers une installation dédiée de scellement et de surveillance</td><td>Département de Sécurité + Bureau d&#39;Administration de la Vie</td></tr><tr><td>Septième étape</td><td>Surveillance continue</td><td>Mener une surveillance continue 24 heures sur 24 de l&#39;état du scellement, vérifiant périodiquement la stabilité du scellement</td><td>Équipe de surveillance</td></tr><tr><td>Huitième étape</td><td>Réévaluation périodique</td><td>Mener une réévaluation complète tous les six mois, évaluant l&#39;état de l&#39;âme maîtresse d&#39;origine, les caractéristiques de l&#39;âme sombre et la stabilité du scellement, déterminant s&#39;il y a une possibilité d&#39;ajuster le type de traitement</td><td>Groupe d&#39;experts d&#39;identification + Comité d&#39;examen éthique</td></tr><tr><td>Neuvième étape</td><td>Entretien du scellement</td><td>Entretenir et renforcer périodiquement le scellement pour prévenir l&#39;affaiblissement ou l&#39;endommagement</td><td>Scelleurs + équipe technique</td></tr></tbody></table><h3 id="v-normes-des-installations-de-scellement-et-de-surveillance" tabindex="-1">(V) Normes des installations de scellement et de surveillance <a class="header-anchor" href="#v-normes-des-installations-de-scellement-et-de-surveillance" aria-label="Permalink to &quot;(V) Normes des installations de scellement et de surveillance&quot;">​</a></h3><ul><li><strong>Localisation</strong> : les installations de scellement et de surveillance sont situées dans des zones reculées à géologie stable, environnement énergétique stable et population clairsemée, ou dans des plans isolés indépendants.</li><li><strong>Construction</strong> : les installations adoptent des structures de protection multiples, comprenant trois couches de protection : barrières physiques, barrières énergétiques et verrouillage spatial.</li><li><strong>Équipement</strong> : équipées de dispositifs de surveillance de scellement de haute précision, de systèmes de renforcement automatiques, de systèmes de réponse d&#39;urgence et de systèmes d&#39;énergie de secours.</li><li><strong>Personnel</strong> : mise en œuvre d&#39;un système de service 24 heures sur 24, équipé de scelleurs, de surveillants, d&#39;agents de sécurité et de personnel de réponse d&#39;urgence.</li><li><strong>Urgence</strong> : formuler divers plans d&#39;urgence pour l&#39;endommagement du scellement, la fuite de l&#39;âme sombre, la disparition de l&#39;âme maîtresse d&#39;origine, etc., avec des exercices réguliers.</li></ul><h3 id="vi-levee-et-conversion-du-scellement" tabindex="-1">(VI) Levée et conversion du scellement <a class="header-anchor" href="#vi-levee-et-conversion-du-scellement" aria-label="Permalink to &quot;(VI) Levée et conversion du scellement&quot;">​</a></h3><p>Dans les circonstances suivantes, le scellement peut être levé ou le type de traitement converti :</p><ul><li><strong>Récupération de l&#39;hôte d&#39;origine</strong> : si l&#39;âme maîtresse d&#39;origine récupère progressivement pendant la période de scellement et possède les conditions de séparation ou de fusion, le scellement peut être levé et converti en type séparation et réinstallation ou fusion symbiotique.</li><li><strong>Réforme de l&#39;âme sombre</strong> : si l&#39;âme sombre présente un potentiel de réforme pendant la période de scellement, le scellement peut être levé dans des conditions contrôlées pour des tentatives de réforme.</li><li><strong>Échec du scellement</strong> : si le scellement subit un endommagement ou un affaiblissement irréparable, et que le danger de l&#39;Entité de Remplacement Sombre est incontrôlable, elle peut être convertie en type dissolution.</li><li><strong>Disparition de l&#39;hôte d&#39;origine</strong> : si l&#39;âme maîtresse d&#39;origine périt complètement pendant la période de scellement et que l&#39;Entité de Remplacement Sombre devient une existence purement sombre, elle peut être convertie en type dissolution ou continuer le scellement selon son danger.</li></ul><h2 id="v-quatrieme-type-traitement-de-dissolution" tabindex="-1">V. Quatrième Type : Traitement de Dissolution <a class="header-anchor" href="#v-quatrieme-type-traitement-de-dissolution" aria-label="Permalink to &quot;V. Quatrième Type : Traitement de Dissolution&quot;">​</a></h2><p>Le traitement de dissolution est le traitement le plus sévère parmi les quatre branches, applicable aux Entités de Remplacement Sombres qui ne peuvent pas être sauvées et sont extrêmement dangereuses ; en annihilant l&#39;âme sombre (et si nécessaire, en annihilant tout le corps), la menace est éliminée.</p><h3 id="i-conditions-d-application-3" tabindex="-1">(I) Conditions d&#39;application <a class="header-anchor" href="#i-conditions-d-application-3" aria-label="Permalink to &quot;(I) Conditions d&#39;application&quot;">​</a></h3><p>Le traitement de dissolution s&#39;applique aux situations suivantes :</p><ol><li>L&#39;Entité de Remplacement Sombre est au cinquième stade (période de remplacement complet) ; l&#39;âme maîtresse d&#39;origine a complètement péri, le corps est entièrement contrôlé par l&#39;âme sombre, devenant une existence purement sombre.</li><li>L&#39;Entité de Remplacement Sombre est au quatrième stade ; l&#39;âme maîtresse d&#39;origine existe encore mais ne peut pas récupérer, la fusion, la séparation et le scellement sont tous infaisables, et son danger continue d&#39;escalader.</li><li>Le niveau de risque de l&#39;Entité de Remplacement Sombre est Quatrième niveau (risque extrêmement élevé), avec un pouvoir destructif de niveau cosmique, menaçant directement la survie de la civilisation, et les autres méthodes de traitement ne peuvent pas contrôler sa menace.</li><li>Dans le traitement de scellement et de surveillance, le scellement a échoué et ne peut pas être réappliqué, et le danger de l&#39;Entité de Remplacement Sombre est incontrôlable.</li><li>Le Comité d&#39;examen éthique des deux âmes examine et approuve le plan de dissolution (les urgences à risque extrêmement élevé peuvent être traitées d&#39;abord et approuvées rétroactivement).</li></ol><h3 id="ii-principes-de-dissolution" tabindex="-1">(II) Principes de dissolution <a class="header-anchor" href="#ii-principes-de-dissolution" aria-label="Permalink to &quot;(II) Principes de dissolution&quot;">​</a></h3><p>Le traitement de dissolution implique l&#39;annihilation de la vie et doit strictement suivre les principes suivants :</p><ul><li><strong>Principe de dernier recours</strong> : la dissolution doit être le dernier recours lorsque toutes les autres méthodes de traitement sont infaisables.</li><li><strong>Principe de proportionnalité</strong> : l&#39;intensité de la dissolution doit correspondre au degré de menace ; l&#39;usage excessif de la force est interdit.</li><li><strong>Principe de souffrance minimale</strong> : la dissolution doit adopter des méthodes sans douleur et rapides autant que possible, réduisant la souffrance de l&#39;âme sombre (et de l&#39;âme maîtresse d&#39;origine, si elle existe encore).</li><li><strong>Principe de respect de l&#39;hôte d&#39;origine</strong> : si l&#39;âme maîtresse d&#39;origine existe encore, elle doit être maintenue lucide et digne autant que possible avant la dissolution ; si nécessaire, permettre à l&#39;hôte d&#39;origine de faire ses adieux aux parents et amis.</li><li><strong>Principe d&#39;enregistrement intégral</strong> : le processus de dissolution est entièrement enregistré, formant une archive complète pour examen et traçabilité.</li><li><strong>Principe d&#39;examen a posteriori</strong> : après la dissolution, mener un examen a posteriori, évaluant la nécessité et l&#39;opportunité de la dissolution et résumant les leçons apprises.</li></ul><h3 id="iii-methodes-de-dissolution" tabindex="-1">(III) Méthodes de dissolution <a class="header-anchor" href="#iii-methodes-de-dissolution" aria-label="Permalink to &quot;(III) Méthodes de dissolution&quot;">​</a></h3><p>Selon le niveau de pouvoir et les caractéristiques de l&#39;Entité de Remplacement Sombre, choisir les méthodes de dissolution suivantes :</p><table tabindex="0"><thead><tr><th>Méthode de dissolution</th><th>Principe</th><th>Cibles applicables</th></tr></thead><tbody><tr><td>Dissolution par Purification de Lumière Sacrée</td><td>Utiliser une énergie de Lumière Sacrée de haute intensité pour purifier l&#39;âme sombre, la faisant se dissiper dans la lumière</td><td>Entités de Remplacement Sombres de niveau de pouvoir faible à moyen</td></tr><tr><td>Art d&#39;Annihilation de l&#39;Âme</td><td>Attaquer et annihiler directement le noyau de l&#39;âme sombre, provoquant sa disparition complète</td><td>Entités de Remplacement Sombres de haut niveau de pouvoir</td></tr><tr><td>Dissolution par Exil Spatial</td><td>Exiler l&#39;Entité de Remplacement Sombre dans l&#39;espace du vide ou la fin des temps, la faisant se dissoudre dans la décroissance spatio-temporelle</td><td>Entités de Remplacement Sombres à forte défense physique</td></tr><tr><td>Dissolution par l&#39;Origine de l&#39;Ancre</td><td>Invoquer l&#39;énergie d&#39;origine de l&#39;Ancre, décomposant l&#39;Entité de Remplacement Sombre et la rendant à l&#39;origine de l&#39;univers</td><td>Entités de Remplacement Sombres dangereuses au niveau cosmique</td></tr><tr><td>Dissolution Conjointe des Puissances de Multiples Plans</td><td>Plusieurs Puissances Suprêmes du Plan unissent leurs forces, utilisant un pouvoir absolu pour supprimer et annihiler l&#39;Entité de Remplacement Sombre</td><td>Entités de Remplacement Sombres de niveau de pouvoir extrêmement élevé</td></tr><tr><td>Dissolution par Auto-Explosion Induite</td><td>Sous contrôle strict, induire l&#39;auto-explosion de l&#39;énergie sombre de l&#39;Entité de Remplacement Sombre, la dissolvant dans l&#39;explosion énergétique</td><td>Entités de Remplacement Sombres à énergie instable</td></tr></tbody></table><h3 id="iv-etapes-du-traitement-1" tabindex="-1">(IV) Étapes du traitement <a class="header-anchor" href="#iv-etapes-du-traitement-1" aria-label="Permalink to &quot;(IV) Étapes du traitement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Étape</th><th>Nom</th><th>Contenu spécifique</th><th>Institution responsable</th></tr></thead><tbody><tr><td>Première étape</td><td>Examen éthique/approbation d&#39;urgence</td><td>En circonstances normales, examiné et approuvé par le Comité d&#39;examen éthique des deux âmes ; dans les urgences à risque extrêmement élevé, ordonné par la personne responsable du plus haut niveau sur site, avec approbation rétroactive</td><td>Comité d&#39;examen éthique des deux âmes / personne responsable du plus haut niveau sur site</td></tr><tr><td>Deuxième étape</td><td>Formulation du plan</td><td>Formuler un plan de dissolution détaillé, comprenant les méthodes de dissolution, l&#39;allocation des forces, les mesures de sécurité, les plans d&#39;urgence et l&#39;évaluation de l&#39;impact environnemental</td><td>Quartier général de commandement de combat + groupe d&#39;experts techniques</td></tr><tr><td>Troisième étape</td><td>Rassemblement des forces</td><td>Rassembler les cultivateurs, le personnel technique, l&#39;équipement et les ressources énergétiques requis pour la dissolution</td><td>Département de Sécurité + cultivateurs avancés</td></tr><tr><td>Quatrième étape</td><td>Verrouillage de zone</td><td>Verrouiller la zone de dissolution, évacuer le personnel environnant et établir des cordons de sécurité</td><td>Département de Sécurité + gouvernement local</td></tr><tr><td>Cinquième étape</td><td>Maîtrise et suppression</td><td>Utiliser d&#39;abord une force de suppression pour contrôler les actions de l&#39;Entité de Remplacement Sombre, empêchant sa fuite ou une plus grande destruction</td><td>Cultivateurs avancés + forces de sécurité</td></tr><tr><td>Sixième étape</td><td>Mise en œuvre de la dissolution</td><td>Mettre en œuvre la dissolution selon le plan de dissolution, avec surveillance intégrale du processus ; en cas d&#39;anomalie, activer immédiatement le plan d&#39;urgence</td><td>Cultivateurs avancés + équipe technique</td></tr><tr><td>Septième étape</td><td>Confirmation de la disparition</td><td>Confirmer que l&#39;âme sombre (et le corps) a complètement péri, inspectant la présence d&#39;énergie résiduelle ou de fragments d&#39;âme</td><td>Équipe de surveillance + groupe d&#39;experts</td></tr><tr><td>Huitième étape</td><td>Restauration environnementale</td><td>Mener une restauration environnementale de la zone de dissolution, éliminant l&#39;énergie sombre résiduelle et rétablissant l&#39;équilibre écologique</td><td>Département de l&#39;Écologie et de l&#39;Environnement</td></tr><tr><td>Neuvième étape</td><td>Gestion des suites</td><td>Notifier les parents et amis de l&#39;hôte d&#39;origine (si l&#39;hôte d&#39;origine a péri), traiter la succession de l&#39;hôte d&#39;origine et mener un soutien psychologique</td><td>Département des affaires civiles + conseillers psychologiques</td></tr><tr><td>Dixième étape</td><td>Archivage et examen a posteriori</td><td>Archiver les enregistrements complets du processus de dissolution et mener un examen a posteriori, évaluant la nécessité et l&#39;opportunité</td><td>Bureau d&#39;Administration de la Vie + Comité d&#39;examen éthique</td></tr></tbody></table><h3 id="v-procedure-de-dissolution-d-urgence" tabindex="-1">(V) Procédure de dissolution d&#39;urgence <a class="header-anchor" href="#v-procedure-de-dissolution-d-urgence" aria-label="Permalink to &quot;(V) Procédure de dissolution d&#39;urgence&quot;">​</a></h3><p>Pour les Entités de Remplacement Sombres de Quatrième niveau (risque extrêmement élevé) qui menacent directement la survie de la civilisation, la procédure de dissolution d&#39;urgence s&#39;applique :</p><ol><li>La personne responsable du plus haut niveau sur site peut ordonner directement le lancement de la dissolution d&#39;urgence sans examen éthique préalable, mais doit faire rapport au Comité d&#39;examen éthique des deux âmes pour enregistrement dans les 24 heures suivant la dissolution.</li><li>La dissolution d&#39;urgence peut mobiliser le plus haut niveau de force et de ressources énergétiques de la civilisation, y compris l&#39;invocation centralisée de l&#39;énergie de l&#39;Ancre et l&#39;action conjointe de plusieurs Puissances Suprêmes du Plan.</li><li>L&#39;objectif prioritaire de la dissolution d&#39;urgence est d&#39;éliminer la menace et de protéger la vie et la sécurité de la civilisation, sans rechercher « l&#39;élégance » ou « l&#39;absence de douleur » de la méthode de dissolution (mais les dommages collatéraux doivent toujours être minimisés autant que possible).</li><li>Après la dissolution d&#39;urgence, une évaluation et une restauration environnementales complètes doivent être menées pour prévenir l&#39;énergie sombre résiduelle et les catastrophes secondaires.</li><li>Les cas de dissolution d&#39;urgence doivent subir un examen et une analyse approfondis a posteriori, résumant les leçons apprises et améliorant les mécanismes d&#39;alerte et de traitement.</li></ol><h2 id="vi-mecanisme-de-conversion-des-quatre-traitements-par-branches" tabindex="-1">VI. Mécanisme de Conversion des Quatre Traitements par Branches <a class="header-anchor" href="#vi-mecanisme-de-conversion-des-quatre-traitements-par-branches" aria-label="Permalink to &quot;VI. Mécanisme de Conversion des Quatre Traitements par Branches&quot;">​</a></h2><p>Le traitement des Entités de Remplacement Sombres n&#39;est pas fixe ; selon les changements de situation pendant le processus de traitement, une conversion entre les quatre branches est possible :</p><table tabindex="0"><thead><tr><th>Direction de conversion</th><th>Conditions de conversion</th><th>Procédure de conversion</th></tr></thead><tbody><tr><td>Fusion → Séparation</td><td>La tentative de fusion échoue ou une instabilité grave apparaît après la fusion</td><td>Réévaluation ; après approbation de l&#39;examen éthique, convertir en séparation</td></tr><tr><td>Fusion → Scellement</td><td>La fusion échoue et la séparation est infaisable ; le contrôle des risques est nécessaire</td><td>Réévaluation ; après approbation de l&#39;examen éthique, convertir en scellement</td></tr><tr><td>Fusion → Dissolution</td><td>La fusion perd le contrôle ; la nouvelle âme a une destructivité incontrôlable</td><td>Évaluation d&#39;urgence ; convertir immédiatement en dissolution</td></tr><tr><td>Séparation → Scellement</td><td>La séparation échoue ou l&#39;hôte d&#39;origine ne peut pas récupérer après la séparation ; le contrôle des risques est nécessaire</td><td>Réévaluation ; après approbation de l&#39;examen éthique, convertir en scellement</td></tr><tr><td>Séparation → Dissolution</td><td>L&#39;âme sombre s&#39;échappe pendant la séparation et est incontrôlable</td><td>Évaluation d&#39;urgence ; convertir immédiatement en dissolution</td></tr><tr><td>Scellement → Fusion</td><td>Pendant la période de scellement, l&#39;âme maîtresse d&#39;origine récupère et possède les conditions de fusion</td><td>Découvert lors de la réévaluation périodique ; après approbation de l&#39;examen éthique, convertir en fusion</td></tr><tr><td>Scellement → Séparation</td><td>Pendant la période de scellement, l&#39;âme maîtresse d&#39;origine récupère et possède les conditions de séparation</td><td>Découvert lors de la réévaluation périodique ; après approbation de l&#39;examen éthique, convertir en séparation</td></tr><tr><td>Scellement → Dissolution</td><td>Le scellement échoue et ne peut pas être réappliqué ; le danger est incontrôlable</td><td>Évaluation d&#39;urgence ; convertir immédiatement en dissolution</td></tr><tr><td>Dissolution → Autres</td><td>La dissolution est le dernier recours ; une fois mise en œuvre, elle est irréversible</td><td>Non applicable</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Le traitement des quatre branches des Entités de Remplacement Sombres est le couronnement de la gouvernance de la vie de la Civilisation Symbiotique de l&#39;Ancre. Du sauvetage actif de la fusion symbiotique, à la coupe précise de la séparation et de la réinstallation, à l&#39;attente patiente du scellement et de la surveillance, au dernier recours de la dissolution, les quatre branches forment un spectre de traitement complet du plus doux au plus sévère, couvrant toutes les situations possibles des Entités de Remplacement Sombres. Ce système de traitement défend à la fois la ligne de base éthique « faire tous les efforts pour sauver chaque âme » et la ligne de base de sécurité « éliminer résolument les menaces incontrôlables », incarnant l&#39;équilibre exquis de la civilisation symbiotique entre l&#39;éthique de la vie et la gouvernance de la sécurité.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>57-黑暗置换体起源与本质 (Origine et Essence des Entités de Remplacement Sombres)</li><li>58-双魂伦理准则 (Directives Éthiques des Deux Âmes)</li><li>54-奇特生命三类处置流程 (Processus de Traitement des Trois Types de Vie Anomale)</li><li>48-司法体系与裁决机制 (Système Judiciaire et Mécanisme de Jugement)</li></ul>',74)])])}const h=t(a,[["render",r]]);export{p as __pageData,h as default};
